export enum SupportedDatastores {
    s3 = 's3',
}

/**
 * The default region used for datastore based measurements when none is provided.
 */
export const DEFAULT_DATASTORE_REGION = 'us-east-1';

/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for connectors inside of Confluent Cloud to pull data from a clients env.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as a Kinesis Connector
 *
 * For the S3 platform Paigo hosts the ingestion (and dead letter) buckets.
 * A dedicated IAM role, scoped to the prefixes owned by the business, is provisioned by Paigo
 * and can be assumed by the account provided in `accountId` by using the returned `externalId`.
 * */
export class DatastoreAccessInformation {
    /**
     * The datastore platform which paigo ingests usage data from. Optional, default is `s3`.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public platform?: SupportedDatastores;

    /**
     * The unique ID of the cloud account which is allowed to write usage data into the datastore. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     * The region of the datastore Paigo ingests usage data from. Optional, default is `us-east-1`.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: DEFAULT_DATASTORE_REGION })
    public region?: string;

    /**
     * Generated by Paigo. The IAM role which can be assumed by the `accountId` to interact with the datastore.
     * @example "arn:aws:iam::647662420899:role/datastore-myBusiness-de388932-a7e1-11ed-afa1-0242ac120002"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public iamRoleArn?: string;

    /**
     * Generated by Paigo. The external ID which must be used when assuming the `iamRoleArn`.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public externalId?: string;

    /**
     * Generated by Paigo. The location usage records must be written to.
     * @example "s3://paigo-usage-record-dump-bucket/myBusiness"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public ingestion?: string;

    /**
     * Generated by Paigo. The location where records which could not be processed are written to.
     * @example "s3://paigo-usage-record-dlq-bucket/myBusiness"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID?: string;

    /**
     * Not persisted, only used to name the resources provisioned for this measurement.
     */
    @ApiHideProperty()
    @IsOptional()
    public measurementId?: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const { accountId, platform, region, iamRoleArn, externalId, ingestion, dlq, businessID, measurementId } =
                datastoreAccessInformation;
            this.platform = platform ? (String(platform).toLowerCase() as SupportedDatastores) : SupportedDatastores.s3;
            this.accountId = accountId;
            this.region = region ? region : DEFAULT_DATASTORE_REGION;
            if (iamRoleArn) {
                this.iamRoleArn = iamRoleArn;
            }
            if (externalId) {
                this.externalId = externalId;
            }
            if (ingestion) {
                this.ingestion = ingestion;
            }
            if (dlq) {
                this.dlq = dlq;
            }
            if (businessID) {
                this.businessID = businessID;
            }
            if (measurementId) {
                this.measurementId = measurementId;
            }
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, ingestion, dlq } =
                datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        businessID,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform,
            accountId,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            businessID,
        });
    }

    /**
     * The name of the IAM role, and of the policy attached to it, provisioned for a datastore measurement.
     */
    public static getRoleName(businessID: string, measurementId: string) {
        return `datastore-${businessID}-${measurementId}`;
    }

    /**
     * The bucket usage records are ingested from.
     */
    public static getIngestionBucket() {
        return `${process.env.DB_MEASUREMENT_BUCKET_NAME}`;
    }

    /**
     * The bucket records which failed processing are written to.
     */
    public static getDLQBucket() {
        return `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`;
    }

    /**
     * The location, inside of the ingestion bucket, owned by a business.
     */
    public static getIngestionLocation(businessID: string) {
        return `s3://${DatastoreAccessInformation.getIngestionBucket()}/${businessID}`;
    }

    /**
     * The location, inside of the dead letter bucket, owned by a business.
     */
    public static getDLQLocation(businessID: string) {
        return `s3://${DatastoreAccessInformation.getDLQBucket()}/${businessID}`;
    }

    /**
     * The trust policy allowing the account of a business to assume the provisioned role,
     * only when the generated external ID is presented.
     */
    public static getTrustPolicy(accountId: string, externalId: string) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };
    }

    /**
     * The permissions granted to the provisioned role.
     * Records can be written to (and read from) the ingestion prefix of the business,
     * records which failed processing can be read from the dead letter prefix of the business.
     */
    public static getAccessPolicy(businessID: string) {
        const ingestionBucket = DatastoreAccessInformation.getIngestionBucket();
        const dlqBucket = DatastoreAccessInformation.getDLQBucket();
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'IngestionAccess',
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject', 's3:ListMultipartUploadParts', 's3:AbortMultipartUpload'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}/${businessID}/*`],
                },
                {
                    Sid: 'DLQAccess',
                    Effect: 'Allow',
                    Action: ['s3:GetObject'],
                    Resource: [`arn:aws:s3:::${dlqBucket}/${businessID}/*`],
                },
                {
                    Sid: 'ListAccess',
                    Effect: 'Allow',
                    Action: ['s3:ListBucket'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}`, `arn:aws:s3:::${dlqBucket}`],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${businessID}/*`],
                        },
                    },
                },
            ],
        };
    }

    private static getIAMClient() {
        return new IAMClient({ region: process.env.AWS_REGION ? process.env.AWS_REGION : DEFAULT_DATASTORE_REGION });
    }

    private static handleIAMError(error, accountId: string) {
        const code = error?.Code || error?.name || error?.code;
        if (code === 'MalformedPolicyDocument' || code === 'MalformedPolicy' || code === 'InvalidInput') {
            throw new BadRequestException(`AccountId: ${accountId} is invalid`);
        }
        throw error;
    }

    /**
     * Provisions the access needed for a business to deliver usage records to Paigo.
     *
     * A uniquely named IAM role, scoped to the ingestion and dead letter prefixes of the business,
     * is created and can only be assumed by the account of the business with the freshly generated external ID.
     *
     * The generated information is set on the passed in access information, which is also returned.
     */
    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation, measurementId?: string) {
        if (!dbAccessInformation) {
            return dbAccessInformation;
        }
        const { accountId, businessID } = dbAccessInformation;
        const platform = dbAccessInformation.platform
            ? String(dbAccessInformation.platform).toLowerCase()
            : SupportedDatastores.s3;
        if (platform !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }
        if (!accountId) {
            throw new BadRequestException('An accountId is required for datastore based measurements');
        }
        const measurementIdForRole = measurementId ? measurementId : dbAccessInformation.measurementId;
        const roleName = DatastoreAccessInformation.getRoleName(businessID, measurementIdForRole);
        const externalId = dbAccessInformation.externalId ? dbAccessInformation.externalId : randomUUID();
        const iamClient = DatastoreAccessInformation.getIAMClient();
        try {
            const { Role } = await iamClient.send(
                new CreateRoleCommand({
                    RoleName: roleName,
                    AssumeRolePolicyDocument: JSON.stringify(
                        DatastoreAccessInformation.getTrustPolicy(accountId, externalId)
                    ),
                })
            );
            await iamClient.send(
                new PutRolePolicyCommand({
                    RoleName: roleName,
                    PolicyName: roleName,
                    PolicyDocument: JSON.stringify(DatastoreAccessInformation.getAccessPolicy(businessID)),
                })
            );
            dbAccessInformation.platform = SupportedDatastores.s3;
            dbAccessInformation.region = dbAccessInformation.region
                ? dbAccessInformation.region
                : DEFAULT_DATASTORE_REGION;
            dbAccessInformation.iamRoleArn =
                Role && Role.Arn ? Role.Arn : `arn:aws:iam::${process.env.AWS_ACCOUNT_ID}:role/${roleName}`;
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.ingestion = DatastoreAccessInformation.getIngestionLocation(businessID);
            dbAccessInformation.dlq = DatastoreAccessInformation.getDLQLocation(businessID);
            return dbAccessInformation;
        } catch (e) {
            return DatastoreAccessInformation.handleIAMError(e, accountId);
        }
    }

    /**
     * Updates the trust of the already provisioned role so that the (potentially new) account of the business
     * can keep assuming it. The role, and the external ID needed to assume it, are preserved.
     */
    public static async updateAccess(dbAccessInformation: DatastoreAccessInformation, measurementId?: string) {
        if (!dbAccessInformation) {
            return dbAccessInformation;
        }
        const { accountId, businessID, iamRoleArn, externalId } = dbAccessInformation;
        const platform = dbAccessInformation.platform
            ? String(dbAccessInformation.platform).toLowerCase()
            : SupportedDatastores.s3;
        if (platform !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }
        if (!accountId) {
            throw new BadRequestException('An accountId is required for datastore based measurements');
        }
        const measurementIdForRole = measurementId ? measurementId : dbAccessInformation.measurementId;
        if (!iamRoleArn || !externalId) {
            // Nothing was provisioned yet, so there is no trust to update.
            return DatastoreAccessInformation.setupAccess(dbAccessInformation, measurementIdForRole);
        }
        const roleName = iamRoleArn.includes('/')
            ? iamRoleArn.substring(iamRoleArn.lastIndexOf('/') + 1)
            : DatastoreAccessInformation.getRoleName(businessID, measurementIdForRole);
        const iamClient = DatastoreAccessInformation.getIAMClient();
        try {
            await iamClient.send(
                new UpdateAssumeRolePolicyCommand({
                    RoleName: roleName,
                    PolicyDocument: JSON.stringify(
                        DatastoreAccessInformation.getTrustPolicy(accountId, externalId)
                    ),
                })
            );
            dbAccessInformation.platform = SupportedDatastores.s3;
            dbAccessInformation.region = dbAccessInformation.region
                ? dbAccessInformation.region
                : DEFAULT_DATASTORE_REGION;
            dbAccessInformation.iamRoleArn = iamRoleArn;
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.ingestion = dbAccessInformation.ingestion
                ? dbAccessInformation.ingestion
                : DatastoreAccessInformation.getIngestionLocation(businessID);
            dbAccessInformation.dlq = dbAccessInformation.dlq
                ? dbAccessInformation.dlq
                : DatastoreAccessInformation.getDLQLocation(businessID);
            return dbAccessInformation;
        } catch (e) {
            return DatastoreAccessInformation.handleIAMError(e, accountId);
        }
    }
}

