     */
    static getDLQBucketName() {
        return `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`;
    }

    /**
     * Turns the key of the source record into a key relative to the bucket it is delivered to.
     * The protocol, bucket and leading slashes are removed, keys which already are relative are untouched.
     */
    static toRelativeKey(sourceKey: string) {
        if (!sourceKey) {
            return sourceKey;
        }
        let key = `${sourceKey}`.trim();
        const absoluteUri = key.match(/^[a-zA-Z0-9]+:\/\/[^/]+\/(.*)$/);
        if (absoluteUri) {
            key = absoluteUri[1];
        }
        return key.replace(/^\/+/, '');
    }

    /**
     * The key a failed record is delivered to. It mirrors the key of the source record.
     */
    static getDLQKey(sourceKey: string) {
        return `${StandardMeasurementEntity.toRelativeKey(sourceKey)}${DLQ_KEY_SUFFIX}`;
    }

    private static serializeFailure(error: unknown) {
        if (!error) {
            return undefined;
        }
        if (error instanceof Error) {
            return { name: error.name, message: error.message };
        }
        if (typeof error === 'object') {
            return { message: `${error['message'] ? error['message'] : JSON.stringify(error)}` };
        }
        return { message: `${error}` };
    }

