import { BadRequestException, Body, Controller, Logger, Post, Req, UseGuards } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { ApiBadRequestResponse, ApiCreatedResponse, ApiExcludeEndpoint, ApiOperation, ApiTags } from '@nestjs/swagger';
import { BasicResponseDTO } from '../basicResponseDTO';
import { CreateUsageDto } from './dto/create-usage.dto';
import { UsageService } from './usage.service';
import { Request } from 'express';
import { DbMeasuredusageDto } from './dto/dbmeasuredUsage.dto';
import { LogGaurd } from '../authz/logGaurd';
import { StandardMeasurementEntity } from '../measurement-config/entities/standardMeasurement.entity';

@ApiTags('Usage')
@Controller('usage')
export class UsageController {
    protected static readonly logger = new Logger(UsageController.name);
    constructor(protected readonly usageService: UsageService) {}

    /**
     * Collect usage data by API-based method.
     * See <a href="https://docs.paigo.tech/measure-usage-and-collect-data/measure-and-collect-usage-data-at-production-scale">Measure and Collect Usage Data At Production Scale</a>
     * for full documentation on Paigo <b>Usage Measurement and Collection</b>.
     * @param createUsageDto
     * @param request
     */
    @ApiCreatedResponse({
        status: 201,
        description: 'OK',
        type: BasicResponseDTO,
    })
    @ApiBadRequestResponse({
        status: 400,
        description: 'Bad Request',
        type: BasicResponseDTO,
    })
    @ApiOperation({ operationId: 'Collect usage data' })
    @UseGuards(AuthGuard('jwt'))
    @Post()
    create(@Body() createUsageDto: CreateUsageDto, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;
        return this.usageService.create({ ...createUsageDto, businessID });
    }
}

/**
 * The internal API used by the datastore connectors.
 */
@ApiTags('Usage')
@Controller('usage')
export class PrivateAPIUsageController extends UsageController {
    /**
     * Collect usage data delivered by a datastore, currently S3, connector.
     *
     * Every request holds a single usage record, `message`, and the key, `s3Key`,
     * of the object the record was read from. The first segment of that key is the
     * businessID owning the ingestion prefix the record was written to.
     *
     * Records which cannot be processed are delivered to the dead letter queue,
     * under the mirrored key of the source object, for manual processing.
     */
    @ApiExcludeEndpoint()
    @UseGuards(LogGaurd, AuthGuard('jwt'))
    @Post('db')
    async dbUsage(@Body() dbMeasuredUsageDto: DbMeasuredusageDto) {
        // Custom validator for DB usage, on failure push to DLQ for manual processing

        UsageController.logger.log('Starting DB Usage Endpoint execution');

        const { message, s3Key } = dbMeasuredUsageDto ? dbMeasuredUsageDto : ({} as DbMeasuredusageDto);
        // TODO: check if the passed in BusinessID is an authorized producer, if not throw message away
        if (!s3Key) {
            throw new BadRequestException('An s3Key must be provided alongside the usage record');
        }
        const [businessID] = StandardMeasurementEntity.toRelativeKey(s3Key).split('/');
        try {
            if (!businessID) {
                throw new BadRequestException(`Unable to determine the businessID from the s3Key: ${s3Key}`);
            }
            const parsed = typeof message === 'string' ? JSON.parse(message) : message;
            if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
                throw new BadRequestException('The usage record must be a single usage measurement');
            }
            return await this.usageService.create({ ...parsed, businessID });
        } catch (error) {
            UsageController.logger.error(`Failed to process the record read from ${s3Key}`, error);
            await StandardMeasurementEntity.publishFailureToDLQ({
                sourceKey: s3Key,
                input: message,
                error,
                metadata: { businessID, processor: PrivateAPIUsageController.name },
            });
            return { message: 'Failed to process usage record, published to the DLQ' };
        }
    }
}

import { BadRequestException } from '@nestjs/common';
import {
    CreateRoleCommand,
    IAMClient,
    PutRolePolicyCommand,
    UpdateAssumeRolePolicyCommand,
} from '@aws-sdk/client-iam';
import { mockClient } from 'aws-sdk-client-mock';
import { measurementMode } from '../dto/create-measurement-config.dto';
import {
    DatastoreAccessInformation,
    MeasurementConfigEntity,
    SupportedDatastores,
} from './measurement-config.entity';

const iamMock = mockClient(IAMClient);

const businessID = 'fakeBusiness';
const measurementId = 'fakeMeasurementId';
const accountId = '623673123435';
const roleName = `datastore-${businessID}-${measurementId}`;
const roleArn = `arn:aws:iam::647662420899:role/${roleName}`;

describe('DatastoreAccessInformation', () => {
    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
    });

    beforeEach(() => {
        iamMock.reset();
        iamMock.on(CreateRoleCommand).resolves({ Role: { Arn: roleArn } as any });
        iamMock.on(PutRolePolicyCommand).resolves({});
        iamMock.on(UpdateAssumeRolePolicyCommand).resolves({});
    });

    it('defaults the platform to s3 and the region to us-east-1', () => {
        const accessInformation = new DatastoreAccessInformation({ accountId, businessID } as any);

        expect(accessInformation.platform).toEqual(SupportedDatastores.s3);
        expect(accessInformation.region).toEqual('us-east-1');
        expect(accessInformation.accountId).toEqual(accountId);
    });

    it('keeps a provided platform and region', () => {
        const accessInformation = new DatastoreAccessInformation({
            accountId,
            businessID,
            platform: SupportedDatastores.s3,
            region: 'eu-west-1',
        } as any);

        expect(accessInformation.platform).toEqual(SupportedDatastores.s3);
        expect(accessInformation.region).toEqual('eu-west-1');
    });

    describe('setupAccess', () => {
        it('provisions a uniquely named role trusting the account of the business', async () => {
            const accessInformation = new DatastoreAccessInformation({ accountId, businessID } as any);

            const result = await DatastoreAccessInformation.setupAccess(accessInformation, measurementId);

            const createRoleCalls = iamMock.commandCalls(CreateRoleCommand);
            expect(createRoleCalls.length).toEqual(1);
            const createRoleInput = createRoleCalls[0].args[0].input;
            expect(createRoleInput.RoleName).toEqual(roleName);

            const trustPolicy = JSON.parse(createRoleInput.AssumeRolePolicyDocument);
            expect(trustPolicy.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${accountId}:root`);
            expect(trustPolicy.Statement[0].Action).toEqual('sts:AssumeRole');
            expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(result.externalId);
            expect(result.externalId).toBeTruthy();
        });

        it('scopes the policy of the role to the prefixes of the business', async () => {
            const accessInformation = new DatastoreAccessInformation({ accountId, businessID } as any);

            await DatastoreAccessInformation.setupAccess(accessInformation, measurementId);

            const putRolePolicyCalls = iamMock.commandCalls(PutRolePolicyCommand);
            expect(putRolePolicyCalls.length).toEqual(1);
            const { RoleName, PolicyName, PolicyDocument } = putRolePolicyCalls[0].args[0].input;
            expect(RoleName).toEqual(roleName);
            expect(PolicyName).toEqual(roleName);

            const policy = JSON.parse(PolicyDocument);
            const resources = policy.Statement.reduce((acc, { Resource }) => acc.concat(Resource), []);
            expect(resources).toContain(
                `arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/*`
            );
            expect(resources).toContain(
                `arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/*`
            );
        });

        it('returns the generated access information alongside the ingestion and dlq locations', async () => {
            const accessInformation = new DatastoreAccessInformation({ accountId, businessID } as any);

            const result = await DatastoreAccessInformation.setupAccess(accessInformation, measurementId);

            expect(result.iamRoleArn).toEqual(roleArn);
            expect(result.externalId).toBeTruthy();
            expect(result.ingestion).toEqual(`s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}`);
            expect(result.dlq).toEqual(`s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}`);
            expect(result.platform).toEqual(SupportedDatastores.s3);
            expect(result.region).toEqual('us-east-1');
        });

        it('generates a fresh external id for every measurement', async () => {
            const first = await DatastoreAccessInformation.setupAccess(
                new DatastoreAccessInformation({ accountId, businessID } as any),
                measurementId
            );
            const second = await DatastoreAccessInformation.setupAccess(
                new DatastoreAccessInformation({ accountId, businessID } as any),
                'anotherMeasurementId'
            );

            expect(first.externalId).not.toEqual(second.externalId);
        });

        it('rejects an invalid accountId', async () => {
            iamMock.on(CreateRoleCommand).rejects(Object.assign(new Error('bad'), { Code: 'MalformedPolicyDocument' }));
            const accessInformation = new DatastoreAccessInformation({ accountId: 'nope', businessID } as any);

            await expect(DatastoreAccessInformation.setupAccess(accessInformation, measurementId)).rejects.toThrow(
                BadRequestException
            );
        });
    });

    describe('updateAccess', () => {
        it('updates the trust of the role while preserving the role and the external id', async () => {
            const provisioned = await DatastoreAccessInformation.setupAccess(
                new DatastoreAccessInformation({ accountId, businessID } as any),
                measurementId
            );
            const { externalId } = provisioned;

            const updated = await DatastoreAccessInformation.updateAccess(
                new DatastoreAccessInformation({ ...provisioned, accountId: '999999999999' } as any),
                measurementId
            );

            expect(updated.iamRoleArn).toEqual(provisioned.iamRoleArn);
            expect(updated.externalId).toEqual(externalId);

            const updateCalls = iamMock.commandCalls(UpdateAssumeRolePolicyCommand);
            expect(updateCalls.length).toEqual(1);
            const { RoleName, PolicyDocument } = updateCalls[0].args[0].input;
            expect(RoleName).toEqual(roleName);
            const trustPolicy = JSON.parse(PolicyDocument);
            expect(trustPolicy.Statement[0].Principal.AWS).toEqual('arn:aws:iam::999999999999:root');
            expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(externalId);
            expect(iamMock.commandCalls(CreateRoleCommand).length).toEqual(1);
        });
    });

    describe('persistence', () => {
        it('round trips the configuration through the db model', async () => {
            const accessInformation = await DatastoreAccessInformation.setupAccess(
                new DatastoreAccessInformation({ accountId, businessID } as any),
                measurementId
            );
            const tags = {};
            const point = { tag: (key, value) => (tags[key] = value), stringField: jest.fn() };

            DatastoreAccessInformation.transformer(accessInformation, point as any);

            expect(tags).toEqual({
                platform: 's3',
                accountId,
                region: 'us-east-1',
                iamRoleArn: accessInformation.iamRoleArn,
                externalId: accessInformation.externalId,
                ingestion: accessInformation.ingestion,
                dlq: accessInformation.dlq,
            });

            const fromDb = DatastoreAccessInformation.dbModelToEntity({ ...tags, businessID });
            expect(fromDb).toEqual(accessInformation);
        });

        it('does not persist the measurementId used to name the provisioned resources', () => {
            const entity = new MeasurementConfigEntity({
                measurementId,
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId } as any,
                businessID,
            } as MeasurementConfigEntity);

            expect(entity.measurementConfiguration).toEqual({
                platform: 's3',
                accountId,
                region: 'us-east-1',
                businessID,
            });
        });
    });

    describe('setupAccessIfRequired', () => {
        it('provisions access for datastore based measurements', async () => {
            const entity = new MeasurementConfigEntity({
                measurementId,
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId } as any,
                businessID,
            } as MeasurementConfigEntity);

            await MeasurementConfigEntity.setupAccessIfRequired(entity);

            expect(iamMock.commandCalls(CreateRoleCommand)[0].args[0].input.RoleName).toEqual(roleName);
            expect((entity.measurementConfiguration as DatastoreAccessInformation).iamRoleArn).toEqual(roleArn);
        });

        it('does not provision access for other measurement modes', async () => {
            const entity = new MeasurementConfigEntity({
                measurementId,
                measurementMode: measurementMode.agentBased,
                measurementConfiguration: { iamRoleArn: 'fakeArn', hostingPlatform: 'k8spod' } as any,
                businessID,
            } as MeasurementConfigEntity);

            await MeasurementConfigEntity.setupAccessIfRequired(entity);

            expect(iamMock.commandCalls(CreateRoleCommand).length).toEqual(0);
        });
    });
});

