private static getIAMClient() {
    return new IAMClient({ region: process.env.AWS_REGION ? process.env.AWS_REGION : DEFAULT_DATASTORE_REGION });
}

/**
 * An account which cannot be trusted by IAM is reported back to the caller,
 * every other failure is audited so that the provisioning can be replayed by hand.
 */
private static handleIAMError(error, accountId: string) {
    const code = error && (error.Code || error.name || error.code);
    if (code === 'MalformedPolicyDocument' || code === 'MalformedPolicy' || code === 'InvalidInput') {
        throw new BadRequestException(`AccountId: ${accountId} is invalid`);
    }
    console.error('Failed to provision the access for a datastore based measurement', error);
    AuditService.publishEvent({
        data: [{ err: error, accountId }],
        message: 'Failed to provision the access for a datastore based measurement',
        topic: AuditScope.ERROR,
    });
}

