import { BadRequestException } from '@nestjs/common';
import { measurementMode } from '../dto/create-measurement-config.dto';
import { DatastoreAccessInformation, MeasurementConfigEntity, SupportedDatastores } from './measurement-config.entity';

jest.mock('@aws-sdk/client-iam', () => {
    const send = jest.fn();
    return {
        mockSend: send,
        IAMClient: jest.fn().mockImplementation(() => ({ send })),
        CreateRoleCommand: jest.fn().mockImplementation((input) => ({ commandName: 'CreateRoleCommand', input })),
        PutRolePolicyCommand: jest.fn().mockImplementation((input) => ({ commandName: 'PutRolePolicyCommand', input })),
        UpdateAssumeRolePolicyCommand: jest
            .fn()
            .mockImplementation((input) => ({ commandName: 'UpdateAssumeRolePolicyCommand', input })),
    };
});

// eslint-disable-next-line @typescript-eslint/no-var-requires
const iam = require('@aws-sdk/client-iam');
const mockSend = iam.mockSend as jest.Mock;

const businessID = 'fakeBusiness';
const measurementId = 'fakeMeasurementId';
const accountId = '623673123435';
const roleName = `datastore-${businessID}-${measurementId}`;
const roleArn = `arn:aws:iam::647662420899:role/${roleName}`;

const commandInputs = (commandName: string) =>
    mockSend.mock.calls.map(([command]) => command).filter((command) => command?.commandName === commandName);

describe('DatastoreAccessInformation', () => {
    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
    });

    beforeEach(() => {
        jest.clearAllMocks();
        mockSend.mockImplementation((command) =>
            command?.commandName === 'CreateRoleCommand' ? Promise.resolve({ Role: { Arn: roleArn } }) : Promise.resolve({})
        );
    });

    it('defaults the platform to s3 and the region to us-east-1', () => {
        const accessInformation = new DatastoreAccessInformation({ accountId, businessID } as any);

        expect(accessInformation.platform).toEqual(SupportedDatastores.s3);
        expect(accessInformation.region).toEqual('us-east-1');
        expect(accessInformation.accountId).toEqual(accountId);
    });

    it('keeps a provided platform and region', () => {
        const accessInformation = new DatastoreAccessInformation({
            accountId,
            businessID,
            platform: SupportedDatastores.s3,
            region: 'eu-west-1',
        } as any);

        expect(accessInformation.platform).toEqual(SupportedDatastores.s3);
        expect(accessInformation.region).toEqual('eu-west-1');
    });

    describe('setupAccess', () => {
        it('provisions a uniquely named role trusting the account of the business', async () => {
            const result = await DatastoreAccessInformation.setupAccess(
                new DatastoreAccessInformation({ accountId, businessID } as any),
                measurementId
            );

            const createRoleInputs = commandInputs('CreateRoleCommand');
            expect(createRoleInputs.length).toEqual(1);
            const { RoleName, AssumeRolePolicyDocument } = createRoleInputs[0].input;
            expect(RoleName).toEqual(roleName);

            const trustPolicy = JSON.parse(AssumeRolePolicyDocument);
            expect(trustPolicy.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${accountId}:root`);
            expect(trustPolicy.Statement[0].Action).toEqual('sts:AssumeRole');
            expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(result.externalId);
            expect(result.externalId).toBeTruthy();
        });

        it('scopes the policy of the role to the prefixes of the business', async () => {
            await DatastoreAccessInformation.setupAccess(
                new DatastoreAccessInformation({ accountId, businessID } as any),
                measurementId
            );

            const putRolePolicyInputs = commandInputs('PutRolePolicyCommand');
            expect(putRolePolicyInputs.length).toEqual(1);
            const { RoleName, PolicyName, PolicyDocument } = putRolePolicyInputs[0].input;
            expect(RoleName).toEqual(roleName);
            expect(PolicyName).toEqual(roleName);

            const policy = JSON.parse(PolicyDocument);
            const resources = policy.Statement.reduce((acc, { Resource }) => acc.concat(Resource), []);
            expect(resources).toContain(`arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/*`);
            expect(resources).toContain(`arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/*`);
            resources.forEach((resource) => expect(resource).not.toContain('anotherBusiness'));
        });

        it('returns the generated access information alongside the ingestion and dlq locations', async () => {
            const result = await DatastoreAccessInformation.setupAccess(
                new DatastoreAccessInformation({ accountId, businessID } as any),
                measurementId
            );

            expect(result.iamRoleArn).toEqual(roleArn);
            expect(result.externalId).toBeTruthy();
            expect(result.ingestion).toEqual(`s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}`);
            expect(result.dlq).toEqual(`s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}`);
            expect(result.platform).toEqual(SupportedDatastores.s3);
            expect(result.region).toEqual('us-east-1');
        });

        it('generates a fresh external id for every measurement', async () => {
            const first = await DatastoreAccessInformation.setupAccess(
                new DatastoreAccessInformation({ accountId, businessID } as any),
                measurementId
            );
            const second = await DatastoreAccessInformation.setupAccess(
                new DatastoreAccessInformation({ accountId, businessID } as any),
                'anotherMeasurementId'
            );

            expect(first.externalId).not.toEqual(second.externalId);
            expect(commandInputs('CreateRoleCommand')[1].input.RoleName).toEqual(
                `datastore-${businessID}-anotherMeasurementId`
            );
        });

        it('reports an accountId which cannot be trusted back to the caller', async () => {
            mockSend.mockRejectedValue(Object.assign(new Error('bad'), { Code: 'MalformedPolicyDocument' }));

            await expect(
                DatastoreAccessInformation.setupAccess(
                    new DatastoreAccessInformation({ accountId: 'nope', businessID } as any),
                    measurementId
                )
            ).rejects.toThrow(BadRequestException);
        });
    });

    describe('updateAccess', () => {
        it('updates the trust of the role while preserving the role and the external id', async () => {
            const provisioned = await DatastoreAccessInformation.setupAccess(
                new DatastoreAccessInformation({ accountId, businessID } as any),
                measurementId
            );
            const { externalId } = provisioned;

            const updated = await DatastoreAccessInformation.updateAccess(
                new DatastoreAccessInformation({ ...provisioned, accountId: '999999999999' } as any),
                measurementId
            );

            expect(updated.iamRoleArn).toEqual(provisioned.iamRoleArn);
            expect(updated.externalId).toEqual(externalId);

            const updateInputs = commandInputs('UpdateAssumeRolePolicyCommand');
            expect(updateInputs.length).toEqual(1);
            const { RoleName, PolicyDocument } = updateInputs[0].input;
            expect(RoleName).toEqual(roleName);
            const trustPolicy = JSON.parse(PolicyDocument);
            expect(trustPolicy.Statement[0].Principal.AWS).toEqual('arn:aws:iam::999999999999:root');
            expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(externalId);
            // The role is never recreated
            expect(commandInputs('CreateRoleCommand').length).toEqual(1);
        });
    });

    describe('persistence', () => {
        it('round trips the configuration through the db model', async () => {
            const accessInformation = await DatastoreAccessInformation.setupAccess(
                new DatastoreAccessInformation({ accountId, businessID } as any),
                measurementId
            );
            const tags = {};
            const point = { tag: (key, value) => (tags[key] = value), stringField: jest.fn() };

            DatastoreAccessInformation.transformer(accessInformation, point as any);

            expect(tags).toEqual({
                platform: 's3',
                accountId,
                region: 'us-east-1',
                iamRoleArn: accessInformation.iamRoleArn,
                externalId: accessInformation.externalId,
                ingestion: accessInformation.ingestion,
                dlq: accessInformation.dlq,
            });

            const fromDb = DatastoreAccessInformation.dbModelToEntity({ ...tags, businessID });
            expect(fromDb).toEqual(accessInformation);
        });

        it('does not persist the measurementId used to name the provisioned resources', () => {
            const entity = new MeasurementConfigEntity({
                measurementId,
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId } as any,
                businessID,
            } as MeasurementConfigEntity);

            expect(entity.measurementConfiguration).toEqual({
                platform: 's3',
                accountId,
                region: 'us-east-1',
                businessID,
            });
        });
    });

    describe('setupAccessIfRequired', () => {
        it('provisions access for datastore based measurements', async () => {
            const entity = new MeasurementConfigEntity({
                measurementId,
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId } as any,
                businessID,
            } as MeasurementConfigEntity);

            await MeasurementConfigEntity.setupAccessIfRequired(entity);

            expect(commandInputs('CreateRoleCommand')[0].input.RoleName).toEqual(roleName);
            expect((entity.measurementConfiguration as DatastoreAccessInformation).iamRoleArn).toEqual(roleArn);
        });

        it('does not provision access for other measurement modes', async () => {
            const entity = new MeasurementConfigEntity({
                measurementId,
                measurementMode: measurementMode.agentBased,
                measurementConfiguration: { iamRoleArn: 'fakeArn', hostingPlatform: 'k8spod' } as any,
                businessID,
            } as MeasurementConfigEntity);

            await MeasurementConfigEntity.setupAccessIfRequired(entity);

            expect(mockSend).not.toHaveBeenCalled();
        });
    });
});

import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { mockClient } from 'aws-sdk-client-mock';
import { DLQ_KEY_SUFFIX, StandardMeasurementEntity } from './standardMeasurement.entity';

const s3Mock = mockClient(S3Client);

const dlqBucket = 'paigo-usage-record-dlq-bucket';
const sourceKey = 'fakeBusiness/topics/usage/partition=0/record.json';

describe('StandardMeasurementEntity.publishFailureToDLQ', () => {
    beforeAll(() => {
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = dlqBucket;
    });

    beforeEach(() => {
        s3Mock.reset();
        s3Mock.on(PutObjectCommand).resolves({});
    });

    it('writes the failed record to the configured DLQ under the mirrored key', async () => {
        await StandardMeasurementEntity.publishFailureToDLQ({
            sourceKey,
            input: '{"recordValue":',
            error: new SyntaxError('Unexpected end of JSON input'),
        });

        const calls = s3Mock.commandCalls(PutObjectCommand);
        expect(calls.length).toEqual(1);
        const { Bucket, Key, Body } = calls[0].args[0].input;
        expect(Bucket).toEqual(dlqBucket);
        expect(Key).toEqual(`${sourceKey}${DLQ_KEY_SUFFIX}`);

        const published = JSON.parse(`${Body}`);
        expect(published.message).toEqual('{"recordValue":');
        expect(published.error.message).toEqual('Unexpected end of JSON input');
        expect(published.sourceKey).toEqual(sourceKey);
        expect(published.timeStamp).toBeTruthy();
    });

    it('mirrors absolute source keys as relative dlq keys', async () => {
        await StandardMeasurementEntity.publishFailureToDLQ({
            sourceKey: `s3://paigo-usage-record-dump-bucket/${sourceKey}`,
            input: 'not json',
            error: new Error('nope'),
        });

        const { Key } = s3Mock.commandCalls(PutObjectCommand)[0].args[0].input;
        expect(Key).toEqual(`${sourceKey}${DLQ_KEY_SUFFIX}`);
    });

    it('keeps relative source keys untouched', () => {
        expect(StandardMeasurementEntity.toRelativeKey(sourceKey)).toEqual(sourceKey);
        expect(StandardMeasurementEntity.toRelativeKey(`/${sourceKey}`)).toEqual(sourceKey);
        expect(StandardMeasurementEntity.getDLQKey(sourceKey)).toEqual(`${sourceKey}${DLQ_KEY_SUFFIX}`);
    });

    it('keeps any additional processing metadata alongside the failed record', async () => {
        await StandardMeasurementEntity.publishFailureToDLQ({
            sourceKey,
            input: { recordValue: 'nope' },
            error: 'invalid record',
            metadata: { businessID: 'fakeBusiness', processor: 'PrivateAPIUsageController' },
        });

        const { Body } = s3Mock.commandCalls(PutObjectCommand)[0].args[0].input;
        const published = JSON.parse(`${Body}`);
        expect(published.input).toEqual({ recordValue: 'nope' });
        expect(published.businessID).toEqual('fakeBusiness');
        expect(published.processor).toEqual('PrivateAPIUsageController');
        expect(published.error.message).toEqual('invalid record');
    });

    it('allows the dlq bucket to be overridden', async () => {
        await StandardMeasurementEntity.publishFailureToDLQ({
            sourceKey,
            bucket: 'another-dlq-bucket',
            input: 'nope',
            error: new Error('nope'),
        });

        const { Bucket } = s3Mock.commandCalls(PutObjectCommand)[0].args[0].input;
        expect(Bucket).toEqual('another-dlq-bucket');
    });
});

import { BadRequestException } from '@nestjs/common';
