import { PrivateAPIUsageController } from './usage.controller';
import { UsageService } from './usage.service';

const s3Mock = mockClient(S3Client);

const dlqBucket = 'paigo-usage-record-dlq-bucket';
const businessID = 'fakeBusiness';
const s3Key = `${businessID}/topics/usage/partition=0/record.json`;
const usageRecord = {
    timeStamp: '2023-02-08T19:24:10Z',
    dimensionId: 'da9611bd-e0f3-4c0d-a754-fda5be730872',
    applicationId: 'e8366954-6f36-47e9-8431-ac95f88b5cc7',
