        s3Mock.on(PutObjectCommand).resolves({});
        mockCreate.mockResolvedValue({ message: 'Measurement created' });
        controller = new PrivateAPIUsageController({ create: mockCreate } as unknown as UsageService);
    });

    it('sends a valid record to the usage service with the businessID of the s3Key', async () => {
        const response = await controller.dbUsage({ message: JSON.stringify(usageRecord) as any, s3Key });

        expect(mockCreate).toHaveBeenCalledWith({ ...usageRecord, businessID });
        expect(response).toEqual({ message: 'Measurement created' });
        expect(s3Mock.commandCalls(PutObjectCommand).length).toEqual(0);
    });

    it('supports records which are already parsed', async () => {
        await controller.dbUsage({ message: usageRecord as any, s3Key });

        expect(mockCreate).toHaveBeenCalledWith({ ...usageRecord, businessID });
    });

    it('publishes malformed records to the DLQ under the mirrored key', async () => {
        const message = '{"recordValue":';

        await controller.dbUsage({ message: message as any, s3Key });

        expect(mockCreate).not.toHaveBeenCalled();
        const calls = s3Mock.commandCalls(PutObjectCommand);
        expect(calls.length).toEqual(1);
        const { Bucket, Key, Body } = calls[0].args[0].input;
        expect(Bucket).toEqual(dlqBucket);
        expect(Key).toEqual(`${s3Key}${DLQ_KEY_SUFFIX}`);
