import { Test, TestingModule } from '@nestjs/testing';
import { DimensionsService } from '../dimensions/dimensions.service';
import { InfluxService } from '../influx/influx.service';
import { SchedulerService } from '../scheduler/scheduler.service';
import { measurementMode } from './dto/create-measurement-config.dto';
import { DatastoreAccessInformation, SupportedDatastores } from './entities/measurement-config.entity';
import { MeasurementConfigService } from './measurement-config.service';

jest.mock('@aws-sdk/client-iam', () => {
    const send = jest.fn();
    return {
        mockSend: send,
        IAMClient: jest.fn().mockImplementation(() => ({ send })),
        CreateRoleCommand: jest.fn().mockImplementation((input) => ({ commandName: 'CreateRoleCommand', input })),
        PutRolePolicyCommand: jest.fn().mockImplementation((input) => ({ commandName: 'PutRolePolicyCommand', input })),
        UpdateAssumeRolePolicyCommand: jest
            .fn()
            .mockImplementation((input) => ({ commandName: 'UpdateAssumeRolePolicyCommand', input })),
    };
});

// eslint-disable-next-line @typescript-eslint/no-var-requires
const iam = require('@aws-sdk/client-iam');
const mockSend = iam.mockSend as jest.Mock;

const businessID = 'fakeBusiness';
const accountId = '623673123435';
const subject = 'fakeSubject';

const commandInputs = (commandName: string) =>
    mockSend.mock.calls.map(([command]) => command).filter((command) => command?.commandName === commandName);

describe('MeasurementConfigService datastore based measurements', () => {
    let service: MeasurementConfigService;
    const mockLoadPoints = jest.fn();
    const mockReadMeasurementConfigData = jest.fn();
    let tags: Record<string, string>;

    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
    });

    beforeEach(async () => {
        jest.clearAllMocks();
        tags = {};
        mockSend.mockImplementation((command) =>
            command?.commandName === 'CreateRoleCommand'
                ? Promise.resolve({ Role: { Arn: `arn:aws:iam::647662420899:role/${command.input.RoleName}` } })
                : Promise.resolve({})
        );
        const module: TestingModule = await Test.createTestingModule({
            providers: [MeasurementConfigService],
            imports: [],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getPoint: () => ({
                            tag: (key, value) => (tags[key] = value),
                            stringField: jest.fn(),
                        }),
                        readMeasurementConfigData: mockReadMeasurementConfigData,
                    };
                }
                if (token === SchedulerService) {
                    return { create: jest.fn() };
                }
                if (token === DimensionsService) {
                    return { transformDtoToEntityInput: jest.fn(), findOneByDimensionId: jest.fn() };
                }
            })
            .compile();

        service = module.get<MeasurementConfigService>(MeasurementConfigService);
    });

    it('provisions and persists the access information of a datastore based measurement', async () => {
        const response = await service.create(
            {
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId } as DatastoreAccessInformation,
                businessID,
            },
            subject
        );

        const { measurementId } = response;
        const roleName = `datastore-${businessID}-${measurementId}`;
        expect(commandInputs('CreateRoleCommand')[0].input.RoleName).toEqual(roleName);
        expect(commandInputs('PutRolePolicyCommand')[0].input.PolicyName).toEqual(roleName);

        const measurementConfiguration = response.measurementConfiguration as DatastoreAccessInformation;
        expect(measurementConfiguration.platform).toEqual(SupportedDatastores.s3);
        expect(measurementConfiguration.region).toEqual('us-east-1');
        expect(measurementConfiguration.accountId).toEqual(accountId);
        expect(measurementConfiguration.iamRoleArn).toEqual(`arn:aws:iam::647662420899:role/${roleName}`);
        expect(measurementConfiguration.externalId).toBeTruthy();
        expect(measurementConfiguration.ingestion).toEqual(
            `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}`
        );
        expect(measurementConfiguration.dlq).toEqual(`s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}`);

        // the generated access information is stored alongside the measurement
        expect(mockLoadPoints).toHaveBeenCalledTimes(1);
        expect(tags).toEqual(
            expect.objectContaining({
                platform: 's3',
                accountId,
                region: 'us-east-1',
                iamRoleArn: measurementConfiguration.iamRoleArn,
                externalId: measurementConfiguration.externalId,
                ingestion: measurementConfiguration.ingestion,
                dlq: measurementConfiguration.dlq,
            })
        );
    });

    it('updates the trust of the provisioned role when the account changes', async () => {
        const {
            measurementId,
            measurementConfiguration: provisioned,
        } = await service.create(
            {
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId } as DatastoreAccessInformation,
                businessID,
            },
            subject
        );
        const { iamRoleArn, externalId } = provisioned as DatastoreAccessInformation;
        mockReadMeasurementConfigData.mockResolvedValue([
            {
                measurementId,
                _value: measurementMode.datastoreBased,
                businessID,
                measurementName: 'fakeMeasurement',
                subject,
                platform: 's3',
                accountId,
                region: 'us-east-1',
                iamRoleArn,
                externalId,
                ingestion: (provisioned as DatastoreAccessInformation).ingestion,
                dlq: (provisioned as DatastoreAccessInformation).dlq,
            },
        ]);

        const response = await service.update(
            {
                measurementId,
                businessID,
                measurementName: undefined,
                measurementConfiguration: { accountId: '999999999999' },
            },
            subject
        );

        const updateInputs = commandInputs('UpdateAssumeRolePolicyCommand');
        expect(updateInputs.length).toEqual(1);
        expect(updateInputs[0].input.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        const trustPolicy = JSON.parse(updateInputs[0].input.PolicyDocument);
        expect(trustPolicy.Statement[0].Principal.AWS).toEqual('arn:aws:iam::999999999999:root');
        expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(externalId);

        const updated = response.measurementConfiguration as DatastoreAccessInformation;
        expect(updated.accountId).toEqual('999999999999');
        expect(updated.iamRoleArn).toEqual(iamRoleArn);
        expect(updated.externalId).toEqual(externalId);
        expect(commandInputs('CreateRoleCommand').length).toEqual(1);
    });

    it('leaves agent based measurements untouched', async () => {
        const response = await service.create(
            {
                measurementMode: measurementMode.agentBased,
                measurementConfiguration: {
                    iamRoleArn: 'fakeArn',
                    externalId: 'fakeExternalId',
                    hostingPlatform: 'k8spod',
                } as any,
                businessID,
            },
            subject
        );

        expect(mockSend).not.toHaveBeenCalled();
        expect(response.measurementConfiguration).toBeUndefined();
        expect(mockLoadPoints).toHaveBeenCalledTimes(1);
    });
});

